"""Canonical four-shade artwork; encoders only change storage layout."""
TILES = [
['00033000','00322300','00333300','00033000','00333300','03233230','00300300','03300330'],
['00033000','00322300','00333300','00033000','00333300','03233230','00300300','00330033'],
['00000000']*8,
['33333333','32222223','32111123','32222223','33333333','32222223','32111123','33333333'],
['00000000','00033000','00322300','03211230','00322300','00033000','00000000','00000000'],
['33333333','31111113','31333313','31300313','31300313','31333313','31111113','33333333'],
['33333333','30000003','30003003','30033003','30330003','33300003','30000003','33333333'],
['00000000','00033000','00300300','03000030','00300300','00033000','00000000','00000000'],
['00000000','00033000','00333300','03333330','00333300','00033000','00000000','00000000'],
['00000000','00000030','00000330','03003300','03333000','00330000','00000000','00000000']]

def encode(planes):
    out=[]
    for tile in TILES:
        for row in tile:
            for p in range(planes):
                out.append(sum(((int(c)>>p)&1)<<(7-i) for i,c in enumerate(row)))
    return bytes(out)

def level():
    out=[]
    for y in range(16):
        for x in range(20):
            tile=3 if x in (0,19) or y in (0,15) or (x==6 and 1<=y<=6 and y!=4) else 2
            if (x,y) in [(4,1),(4,5),(8,5)]:tile=4
            if (x,y)==(10,5):tile=5
            out.append(tile)
    return bytes(out)
